library.logic:
const high = Math.floor(t * props.freq * 2) % 2 === 1;
state.light = high ? 1 : 0;
return { OUT: high ? props.V : 0 };

const v = (inp.A || 0) - (inp.K || 0);
state.light = v >= props.seuil ? Math.min(1, v / 5 + 0.3) : 0;
return {};

state.speed = ((inp.A || 0) - (inp.B || 0)) / props.Vmax;
state.text = Math.round(state.speed * 100) + ' %';
return {};

const clk = (inp.CLK || 0) >= props.seuil;
if (clk && !state.prev) state.q = (inp.D || 0) >= props.seuil;
state.prev = clk;
return { Q: state.q ? props.V : 0, nQ: state.q ? 0 : props.V };

// Un bit vaut 1 si sa tension dépasse le seuil (un fil flottant vaut 0)
const bit = v => (v || 0) >= props.seuil ? 1 : 0;
const A = bit(inp.A0) + 2 * bit(inp.A1) + 4 * bit(inp.A2) + 8 * bit(inp.A3);
const B = bit(inp.B0) + 2 * bit(inp.B1) + 4 * bit(inp.B2) + 8 * bit(inp.B3);
const op = bit(inp.OP0) + 2 * bit(inp.OP1);   // 0 : +   1 : −   2 : ×   3 : ÷

let r = 0, neg = false, err = false;
if (op === 0) r = A + B;
else if (op === 1) { r = A - B; if (r < 0) { neg = true; r = -r; } }
else if (op === 2) r = A * B;
else if (B === 0) err = true;
else r = Math.floor(A / B);

const sym = ['+', '−', '×', '÷'][op];
state.text = A + ' ' + sym + ' ' + B + ' = ' + (err ? 'ERR' : (neg ? '-' : '') + r + (op === 3 ? ' r' + (A % B) : ''));

// Résultat en binaire sur 8 bits (valeur absolue)
const out = { NEG: neg ? props.V : 0, ERR: err ? props.V : 0 };
for (let i = 0; i < 8; i++) out['R' + i] = (r >> i) & 1 ? props.V : 0;
return out;

const bit = v => (v || 0) >= props.seuil ? 1 : 0;
let n = 0;
for (let i = 0; i < 8; i++) n += bit(inp['D' + i]) << i;
state.text = bit(inp.ERR) ? 'ERREUR' : (bit(inp.NEG) ? '-' : '') + n + ' (' + n.toString(2).padStart(8, '0') + ')';
return {};

const bit = v => (v || 0) >= props.seuil ? 1 : 0;
state.text = ['+ addition', '− soustraction', '× multiplication', '÷ division'][bit(inp.OP0) + 2 * bit(inp.OP1)];
return {};
